class Game {
  constructor() {
    this.container = document.createElement('div');
    document.body.appendChild(this.container);

    this.renderer = new THREE.WebGLRenderer({ antialias: true });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.physicallyCorrectLights = true;
    this.container.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x87CEEB);

    this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    this.camera.position.set(0, 20, 30);
    this.camera.lookAt(0, 0, 0);

    this.world = new CANNON.World();
    this.world.gravity.set(0, -9.82, 0);
    this.world.broadphase = new CANNON.SAPBroadphase(this.world);

    this.clock = new THREE.Clock();

    this.karts = [];
    this.track = null;
    this.playerKart = null;
    this.keys = {};

    this.init();
  }

  init() {
    this.setupLights();
    this.createTrack();
    this.createKart('player', 0, 0, 0, true);
    this.createKart('ai1', 10, 0, 10, false);
    this.createKart('ai2', -10, 0, 10, false);
    this.createKart('ai3', 0, 0, 20, false);

    this.setupControls();
    this.setupEnvironment();

    this.animate();
  }

  setupLights() {
    this.ambientLight = new THREE.AmbientLight(0x404040);
    this.scene.add(this.ambientLight);

    this.sunLight = new THREE.DirectionalLight(0xffffff, 1);
    this.sunLight.position.set(10, 20, 10);
    this.sunLight.castShadow = true;
    this.sunLight.shadow.mapSize.width = 2048;
    this.sunLight.shadow.mapSize.height = 2048;
    this.scene.add(this.sunLight);

    this.pointLight = new THREE.PointLight(0xff6600, 2, 50);
    this.pointLight.position.set(0, 5, 0);
    this.scene.add(this.pointLight);
  }

  createTrack() {
    // Simple track geometry
    const trackGeometry = new THREE.BoxGeometry(100, 2, 100);
    const trackMaterial = new THREE.MeshStandardMaterial({ color: 0x444444 });
    this.track = new THREE.Mesh(trackGeometry, trackMaterial);
    this.track.receiveShadow = true;
    this.track.position.y = -1;
    this.scene.add(this.track);

    // Track edges
    const edgeGeometry = new THREE.BoxGeometry(102, 0.5, 102);
    const edgeMaterial = new THREE.MeshStandardMaterial({ color: 0x222222 });
    const edges = new THREE.Mesh(edgeGeometry, edgeMaterial);
    edges.position.y = -1.25;
    this.scene.add(edges);
  }

  createKart(name, x, z, rotation, isPlayer) {
    const kartGroup = new THREE.Group();

    // Kart body
    const bodyGeometry = new THREE.BoxGeometry(2, 1, 3);
    const bodyMaterial = new THREE.MeshStandardMaterial({ color: this.getRandomColor() });
    const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    body.castShadow = true;
    body.position.y = 1;
    kartGroup.add(body);

    // Wheels
    const wheelGeometry = new THREE.CylinderGeometry(0.5, 0.5, 0.8, 16);
    const wheelMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

    const positions = [
      new THREE.Vector3(-1, 0, 1),
      new THREE.Vector3(1, 0, 1),
      new THREE.Vector3(-1, 0, -1),
      new THREE.Vector3(1, 0, -1)
    ];

    const wheels = [];
    positions.forEach(pos => {
      const wheel = new THREE.Mesh(wheelGeometry, wheelMaterial);
      wheel.position.copy(pos);
      wheel.rotation.x = Math.PI / 2;
      wheel.castShadow = true;
      kartGroup.add(wheel);
      wheels.push(wheel);
    });

    kartGroup.position.set(x, 1, z);
    kartGroup.rotation.y = rotation;
    this.scene.add(kartGroup);

    // Physics body
    const shape = new CANNON.Box(new CANNON.Vec3(1, 0.5, 1.5));
    const body = new CANNON.Body({
      mass: isPlayer ? 100 : 50,
      position: new CANNON.Vec3(x, 1, z),
      shape: shape
    });
    this.world.add(body);

    const kart = {
      name: name,
      mesh: kartGroup,
      physics: body,
      wheels: wheels,
      velocity: new THREE.Vector3(),
      boost: 0,
      isPlayer: isPlayer,
      drift: 0,
      getDrift() {
        return this.drift;
      },
      setDrift(value) {
        this.drift = Math.max(0, Math.min(100, value));
      }
    };

    if (isPlayer) {
      this.playerKart = kart;
    }

    this.karts.push(kart);
  }

  getRandomColor() {
    const colors = [0xff0000, 0x0000ff, 0x00ff00, 0xffff00, 0xff00ff, 0x00ffff];
    return colors[Math.floor(Math.random() * colors.length)];
  }

  setupControls() {
    window.addEventListener('keydown', (e) => {
      this.keys[e.code] = true;
      if (e.code === 'Space') {
        e.preventDefault();
      }
    });

    window.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
    });

    window.addEventListener('resize', () => {
      this.camera.aspect = window.innerWidth / window.innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(window.innerWidth, window.innerHeight);
    });
  }

  setupEnvironment() {
    // Create ground for physics
    const groundShape = new CANNON.Plane();
    const groundBody = new CANNON.Body({ mass: 0 });
    groundBody.addShape(groundShape);
    groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
    this.world.add(groundBody);
  }

  updatePhysics(dt) {
    this.world.step(dt);

    // Update kart positions from physics
    this.karts.forEach(kart => {
      const mesh = kart.mesh;
      const physics = kart.physics;

      mesh.position.copy(physics.position);
      mesh.quaternion.copy(physics.quaternion);

      // Apply drift effect
      if (kart.drift > 0) {
        const driftFactor = kart.drift / 100;
        const driftDirection = new THREE.Vector3(0, 0, 1).applyQuaternion(mesh.quaternion);
        const driftVelocity = new THREE.Vector3()
          .copy(driftDirection)
          .multiplyScalar(driftFactor * 2);

        physics.velocity.x += driftVelocity.x * dt;
        physics.velocity.z += driftVelocity.z * dt;
      }

      // Update wheels rotation
      const speed = Math.sqrt(physics.velocity.x ** 2 + physics.velocity.z ** 2);
      const rotationSpeed = speed * 0.1;

      kart.wheels.forEach((wheel, index) => {
        wheel.rotation.x = Math.PI / 2;
        if (speed > 0.1) {
          wheel.rotation.x += rotationSpeed * (index < 2 ? -1 : 1);
        }
      });
    });
  }

  updateControls(dt) {
    if (!this.playerKart) return;

    const kart = this.playerKart;
    const physics = kart.physics;
    const speed = Math.sqrt(physics.velocity.x ** 2 + physics.velocity.z ** 2);

    // Forward/backward
    if (this.keys['KeyW'] || this.keys['ArrowUp']) {
      physics.applyForce(new CANNON.Vec3(0, 0, 100), physics.position);
    }
    if (this.keys['KeyS'] || this.keys['ArrowDown']) {
      physics.applyForce(new CANNON.Vec3(0, 0, -100), physics.position);
    }

    // Left/right steering
    if (this.keys['KeyA'] || this.keys['ArrowLeft']) {
      physics.applyTorque(new CANNON.Vec3(0, -50, 0));
      // Increase drift when turning and moving
      if (speed > 2) {
        kart.setDrift(kart.getDrift() + 10 * dt);
      }
    }
    if (this.keys['KeyD'] || this.keys['ArrowRight']) {
      physics.applyTorque(new CANNON.Vec3(0, 50, 0));
      // Increase drift when turning and moving
      if (speed > 2) {
        kart.setDrift(kart.getDrift() + 10 * dt);
      }
    }

    // Drift boost (reduce drift for speed boost)
    if (kart.getDrift() > 30 && (this.keys['KeyA'] || this.keys['KeyD'])) {
      const boostAmount = kart.getDrift() * 0.05 * dt;
      kart.boost = Math.min(100, kart.boost + boostAmount);
      kart.setDrift(kart.getDrift() - boostAmount * 2);
    }

    // Apply boost to physics
    if (kart.boost > 0) {
      const boostForce = kart.getDrift() > 50 ? 300 : 150;
      physics.velocity.x += Math.cos(physics.quaternion.y) * boostForce * dt;
      physics.velocity.z += Math.sin(physics.quaternion.y) * boostForce * dt;
      kart.boost *= 0.95;
    }

    // Drift decay when not turning
    if (kart.getDrift() > 0) {
      const decay = speed > 5 ? 20 : 5;
      kart.setDrift(kart.getDrift() - decay * dt);
    }
  }

  updateCamera() {
    if (!this.playerKart) return;

    const targetPosition = new THREE.Vector3()
      .copy(this.playerKart.mesh.position)
      .add(new THREE.Vector3(0, 15, 30));

    this.camera.position.lerp(targetPosition, 0.1);
    this.camera.lookAt(this.playerKart.mesh.position);
  }

  updateAI(dt) {
    this.karts.forEach(kart => {
      if (kart.isPlayer) return;

      const physics = kart.physics;
      const playerPos = this.playerKart.mesh.position;
      const kartPos = kart.mesh.position;

      const direction = new THREE.Vector3()
        .subVectors(playerPos, kartPos)
        .normalize();

      const distance = kartPos.distanceTo(playerPos);

      if (distance > 10) {
        // Move towards player
        physics.applyForce(
          new CANNON.Vec3(direction.x * 50, 0, direction.z * 50),
          physics.position
        );

        // Simple steering
        const angle = Math.atan2(direction.z, direction.x);
        const currentAngle = physics.quaternion.y;
        const angleDiff = angle - currentAngle;

        physics.applyTorque(new CANNON.Vec3(0, angleDiff * 100, 0));

        // Random drift sometimes
        if (Math.random() < 0.02) {
          kart.setDrift(kart.getDrift() + 20);
        }
      } else {
        // Try to drift around
        if (Math.random() < 0.05) {
          physics.applyTorque(new CANNON.Vec3(0, Math.random() * 20 - 10, 0));
          kart.setDrift(kart.getDrift() + 15);
        }
      }
    });
  }

  animate() {
    requestAnimationFrame(() => this.animate());

    const dt = this.clock.getDelta();

    this.updatePhysics(dt);
    this.updateControls(dt);
    this.updateCamera();
    this.updateAI(dt);

    this.renderer.render(this.scene, this.camera);
  }
}}

// Start the game
window.addEventListener('DOMContentLoaded', () => {
  new Game();
});

const fs = require('fs');
const path = require('path');
const { minify } = require('terser');

const srcDir = path.join(__dirname, '../src');
const distDir = path.join(__dirname, '../dist');

function ensureDir(dir) {
    if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
    }
}

async function minifyJs(file) {
    const content = fs.readFileSync(file, 'utf8');
    const result = await minify(content, {
        mangle: true,
        compress: true,
        format: {
            comments: false
        }
    });
    return result.code;
}

async function build() {
    console.log('Building Mario Kart 3D Racer...');

    ensureDir(distDir);

    // Copy and minify main game files
    const files = ['Game.js'];

    for (const file of files) {
        const srcPath = path.join(srcDir, file);
        const distPath = path.join(distDir, file);

        if (fs.existsSync(srcPath)) {
            let content = fs.readFileSync(srcPath, 'utf8');

            // Add minification
            if (file.endsWith('.js')) {
                content = await minifyJs(srcPath);
            }

            fs.writeFileSync(distPath, content);
            console.log(`✓ Built ${file}`);
        }
    }

    // Copy HTML file
    const htmlSrc = path.join(__dirname, '../index.html');
    const htmlDest = path.join(distDir, 'index.html');
    if (fs.existsSync(htmlSrc)) {
        fs.copyFileSync(htmlSrc, htmlDest);
        console.log('✓ Copied index.html');
    }

    // Create a simple index.js for the main game entry
    const gameEntry = `// Mario Kart 3D Racer - Game Entry Point
import './Game.js';

// Game is automatically instantiated when DOM is loaded
console.log('Mario Kart 3D Racer loaded successfully!');
`;

    fs.writeFileSync(path.join(distDir, 'index.js'), gameEntry);
    console.log('✓ Created game entry point');

    console.log('\nBuild complete! Files are in the dist/ directory.');
}

if (require.main === module) {
    build().catch(console.error);
}

module.exports = { build };

class Scene {
  constructor() {
    this.scene = new THREE.Scene();
    this.lights = [];
    this.particles = [];
    this.environment = 'day';
  }

  setup() {
    this.setupBackground();
    this.setupLights();
    this.createEnvironment();
    this.createParticles();
  }

  setupBackground() {
    // Sky gradient
    const skyGeometry = new THREE.SphereGeometry(500, 32, 32);
    const skyMaterial = new THREE.ShaderMaterial({
      uniforms: {
        topColor: { value: new THREE.Color(0x87CEEB) },
        bottomColor: { value: new THREE.Color(0xE0F7FA) },
        offset: { value: 0.5 },
        exponent: { value: 0.5 }
      },
      vertexShader: `varying vec3 vWorldPosition;
        void main() {
          vec4 worldPosition = modelMatrix * vec4(position, 1.0);
          vWorldPosition = worldPosition.xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
      fragmentShader: `uniform vec3 topColor;
        uniform vec3 bottomColor;
        uniform float offset;
        uniform float exponent;
        varying vec3 vWorldPosition;
        void main() {
          float h = normalize(vWorldPosition).y;
          h = max(h, 0.0);
          h = offset + exponent * h;
          gl_FragColor = vec4(mix(bottomColor, topColor, h), 1.0);
        }`,
      side: THREE.BackSide
    });

    const sky = new THREE.Mesh(skyGeometry, skyMaterial);
    sky.position.y = -100;
    this.scene.add(sky);
  }

  setupLights() {
    // Ambient light
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);
    this.scene.add(ambientLight);
    this.lights.push(ambientLight);

    // Directional light (sun)
    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
    directionalLight.position.set(100, 100, 50);
    directionalLight.castShadow = true;
    directionalLight.shadow.camera.left = -200;
    directionalLight.shadow.camera.right = 200;
    directionalLight.shadow.camera.top = 200;
    directionalLight.shadow.camera.bottom = -200;
    directionalLight.shadow.camera.near = 0.1;
    directionalLight.shadow.camera.far = 500;
    this.scene.add(directionalLight);
    this.lights.push(directionalLight);

    // Point lights for atmosphere
    const pointLight1 = new THREE.PointLight(0xff6600, 0.5, 100);
    pointLight1.position.set(-50, 20, 30);
    this.scene.add(pointLight1);
    this.lights.push(pointLight1);

    const pointLight2 = new THREE.PointLight(0x00ffff, 0.3, 80);
    pointLight2.position.set(50, 20, -30);
    this.scene.add(pointLight2);
    this.lights.push(pointLight2);
  }

  createEnvironment() {
    // Create a simple landscape with hills
    const hillGeometry = new THREE.SphereGeometry(20, 16, 16);
    const hillMaterial = new THREE.MeshStandardMaterial({ color: 0x45a049 });

    const hills = [];
    for (let i = 0; i < 10; i++) {
      const hill = new THREE.Mesh(hillGeometry, hillMaterial);
      hill.position.x = (i - 5) * 40;
      hill.position.z = -Math.random() * 100 - 50;
      hill.position.y = Math.random() * 15;
      hill.scale.set(2, 1.5, 2);
      this.scene.add(hill);
      hills.push(hill);
    }

    // Create some trees
    for (let i = 0; i < 15; i++) {
      this.createTree(i * 30 - 150, Math.random() * 60 - 30);
    }
  }

  createTree(x, z) {
    // Tree trunk
    const trunkGeometry = new THREE.CylinderGeometry(0.5, 0.5, 8, 8);
    const trunkMaterial = new THREE.MeshStandardMaterial({ color: 0x8B4513 });
    const trunk = new THREE.Mesh(trunkGeometry, trunkMaterial);
    trunk.position.set(x, 4, z);
    this.scene.add(trunk);

    // Tree foliage
    const foliageGeometry = new THREE.ConeGeometry(6, 12, 8);
    const foliageMaterial = new THREE.MeshStandardMaterial({ color: 0x228B22 });
    const foliage = new THREE.Mesh(foliageGeometry, foliageMaterial);
    foliage.position.set(x, 10, z);
    this.scene.add(foliage);
  }

  createParticles() {
    // Create dust particles for kart movement
    const particlesGeometry = new THREE.BufferGeometry();
    const particlesCount = 100;
    const posArray = new Float32Array(particlesCount * 3);

    for (let i = 0; i < particlesCount * 3; i++) {
      posArray[i] = (Math.random() - 0.5) * 200;
    }

    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));

    const particlesMaterial = new THREE.PointsMaterial({
      size: 0.5,
      color: 0x888888,
      transparent: true,
      opacity: 0.6
    });

    const particles = new THREE.Points(particlesGeometry, particlesMaterial);
    this.scene.add(particles);
    this.particles.push(particles);

    // Create dust trail at specific positions
    this.dustTrails = [];
    for (let i = 0; i < 5; i++) {
      const trailGeometry = new THREE.BufferGeometry();
      const trailMaterial = new THREE.PointsMaterial({
        size: 0.3,
        color: 0xcccccc,
        transparent: true,
        opacity: 0.4
      });
      const trail = new THREE.Points(trailGeometry, trailMaterial);
      this.scene.add(trail);
      this.dustTrails.push(trail);
    }
  }

  updateDust(kart) {
    if (kart && kart.physics) {
      const pos = kart.mesh.position;
      // Add dust particles at kart position
      for (let i = 0; i < this.dustTrails.length; i++) {
        // This would be updated in the main game loop
        const trail = this.dustTrails[i];
        // In a real implementation, we'd add particles to trails
      }
    }
  }

  changeEnvironment(type) {
    this.environment = type;

    // Adjust lighting based on environment
    if (type === 'night') {
      this.lights.forEach(light => {
        if (light.isAmbientLight) {
          light.intensity = 0.1;
        } else if (light.isDirectionalLight) {
          light.intensity = 0.3;
          light.color.setHex(0x222222);
        } else if (light.isPointLight) {
          light.intensity = 0;
        }
      });

      // Add moon
      if (!this.moon) {
        const moonGeometry = new THREE.SphereGeometry(5, 16, 16);
        const moonMaterial = new THREE.MeshStandardMaterial({
          color: 0xffffaa,
          emissive: 0xffffaa,
          emissiveIntensity: 0.5
        });
        this.moon = new THREE.Mesh(moonGeometry, moonMaterial);
        this.moon.position.set(100, 50, -100);
        this.scene.add(this.moon);
      }
    } else {
      // Restore day lighting
      this.lights.forEach(light => {
        if (light.isAmbientLight) {
          light.intensity = 0.3;
        } else if (light.isDirectionalLight) {
          light.intensity = 1.0;
          light.color.setHex(0xffffff);
        } else if (light.isPointLight) {
          light.intensity = 0.5;
          light.color.setHex(0xff6600);
        }
      });

      if (this.moon) {
        this.scene.remove(this.moon);
        this.moon = null;
      }
    }
  }

  updateTimeOfDay(hours) {
    const time = hours % 24;

    if (time >= 6 && time < 18) {
      this.changeEnvironment('day');
    } else {
      this.changeEnvironment('night');
    }
  }

  animateDust() {
    // Animate dust particles
    this.particles.forEach(particles => {
      particles.rotation.y += 0.001;
    });
  }

  getScene() {
    return this.scene;
  }
}}

export { Scene };

