// Three.js utilities for the racing game
const ThreeUtils = {
  // Create a simple gradient background
  createSkyGradient: (renderer, color1, color2) => {
    const canvas = document.createElement('canvas');
    const context = canvas.getContext('2d');
    canvas.width = 2;
    canvas.height = 512;

    const gradient = context.createLinearGradient(0, 0, 0, 512);
    gradient.addColorStop(0, '#' + color1.toString(16).padStart(6, '0'));
    gradient.addColorStop(1, '#' + color2.toString(16).padStart(6, '0'));
    context.fillStyle = gradient;
    context.fillRect(0, 0, 2, 512);

    const texture = new THREE.CanvasTexture(canvas);
    return texture;
  },

  // Create a simple kart model
  createKartModel: (color) => {
    const group = new THREE.Group();

    // Kart body
    const bodyGeometry = new THREE.BoxGeometry(2, 0.5, 2.5);
    const bodyMaterial = new THREE.MeshStandardMaterial({ color: color });
    const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    body.position.y = 0.3;
    group.add(body);

    // Wheels
    const wheelGeometry = new THREE.CylinderGeometry(0.3, 0.3, 0.6, 8);
    const wheelMaterial = new THREE.MeshStandardMaterial({ color: 0x111111 });

    const wheelPositions = [
      [-0.8, 0, 1.2],
      [0.8, 0, 1.2],
      [-0.8, 0, -1.2],
      [0.8, 0, -1.2]
    ];

    wheelPositions.forEach(pos => {
      const wheel = new THREE.Mesh(wheelGeometry, wheelMaterial);
      wheel.position.set(pos[0], pos[1], pos[2]);
      wheel.rotation.x = Math.PI / 2;
      group.add(wheel);
    });

    return group;
  },

  // Create track segments
  createTrackSegment: (x, z, width, length) => {
    const segmentGeometry = new THREE.BoxGeometry(width, 0.5, length);
    const segmentMaterial = new THREE.MeshStandardMaterial({ color: 0x444444 });
    const segment = new THREE.Mesh(segmentGeometry, segmentMaterial);
    segment.position.set(x, 0, z);
    return segment;
  },

  // Create a simple AI kart with different behavior
  createAIKart: (index) => {
    const colors = [0xff0000, 0x0000ff, 0x00ff00];
    const kart = new ThreeUtils.createKartModel(colors[index % colors.length]);
    return kart;
  },

  // Create particle effect for drifting
  createDriftEffect: (position) => {
    const particles = [];
    for (let i = 0; i < 20; i++) {
      const geometry = new THREE.SphereGeometry(0.1, 4, 4);
      const material = new THREE.MeshBasicMaterial({
        color: 0xff6600,
        transparent: true,
        opacity: 0.7
      });
      const particle = new THREE.Mesh(geometry, material);
      particle.position.copy(position);
      particles.push(particle);
    }
    return particles;
  },

  // Normalize vector
  normalizeVector: (x, z) => {
    const length = Math.sqrt(x * x + z * z);
    if (length === 0) return { x: 0, z: 0 };
    return { x: x / length, z: z / length };
  }
};

// Export for use in other modules
if (typeof module !== 'undefined' && module.exports) {
  module.exports = ThreeUtils;
}
if (typeof window !== 'undefined') {
  window.ThreeUtils = ThreeUtils;
}

// Physics utilities for the racing game
const PhysicsUtils = {
  // Calculate drift force based on speed and steering angle
  calculateDriftForce: (velocity, steeringAngle, maxDrift) => {
    const speed = Math.sqrt(velocity.x * velocity.x + velocity.z * velocity.z);
    const steeringForce = Math.abs(steeringAngle);
    const driftFactor = (speed / 20) * (steeringForce / Math.PI);
    return Math.min(driftFactor * maxDrift, maxDrift);
  },

  // Apply gravity to physics body
  applyGravity: (body, dt) => {
    body.velocity.y += body.mass * -9.82 * dt;
  },

  // Apply friction to physics body
  applyFriction: (body, dt) => {
    const friction = 0.1;
    const velocityMagnitude = Math.sqrt(body.velocity.x ** 2 + body.velocity.z ** 2);
    if (velocityMagnitude > 0) {
      const frictionForce = velocityMagnitude * friction;
      const frictionX = (body.velocity.x / velocityMagnitude) * -frictionForce;
      const frictionZ = (body.velocity.z / velocityMagnitude) * -frictionForce;
      body.velocity.x += frictionX * dt;
      body.velocity.z += frictionZ * dt;
    }
  },

  // Apply engine power to physics body
  applyEnginePower: (body, power, dt) => {
    if (power > 0) {
      const force = power * dt;
      body.velocity.x += force * Math.cos(body.quaternion.y);
      body.velocity.z += force * Math.sin(body.quaternion.y);
    }
  },

  // Calculate wheel rotation speed
  calculateWheelRotation: (velocity, radius) => {
    const speed = Math.sqrt(velocity.x ** 2 + velocity.z ** 2);
    return speed / radius;
  },

  // Apply steering torque to physics body
  applySteering: (body, steeringAngle, maxTorque) => {
    const torque = steeringAngle * maxTorque;
    body.torque.y = torque;
  },

  // Check if kart is moving for drift calculation
  isMoving: (body) => {
    const velocity = Math.sqrt(body.velocity.x ** 2 + body.velocity.z ** 2);
    return velocity > 0.1;
  },

  // Calculate kart's forward direction
  getForwardDirection: (quaternion) => {
    return new CANNON.Vec3(
      Math.cos(quaternion.y),
      0,
      Math.sin(quaternion.y)
    );
  },

  // Apply drift boost effect
  applyDriftBoost: (body, boostAmount, dt) => {
    const forward = PhysicsUtils.getForwardDirection(body.quaternion);
    const boostForce = boostAmount * dt;
    body.velocity.x += forward.x * boostForce;
    body.velocity.z += forward.z * boostForce;
  },

  // Update kart velocity based on input
  updateVelocity: (body, input, dt, maxSpeed) => {
    const velocity = body.velocity;
    const speed = Math.sqrt(velocity.x ** 2 + velocity.z ** 2);

    if (input.forward) {
      const force = input.forward * dt;
      velocity.x += Math.cos(body.quaternion.y) * force;
      velocity.z += Math.sin(body.quaternion.y) * force;
    }

    if (input.backward) {
      const force = input.backward * dt;
      velocity.x -= Math.cos(body.quaternion.y) * force;
      velocity.z -= Math.sin(body.quaternion.y) * force;
    }

    // Apply steering
    if (input.steering !== 0) {
      PhysicsUtils.applySteering(body, input.steering, 100);
    }

    // Apply friction
    PhysicsUtils.applyFriction(body, dt);

    // Limit speed
    if (speed > maxSpeed) {
      const ratio = maxSpeed / speed;
      velocity.x *= ratio;
      velocity.z *= ratio;
    }
  }
};

// Export for use in other modules
if (typeof module !== 'undefined' && module.exports) {
  module.exports = PhysicsUtils;
}
if (typeof window !== 'undefined') {
  window.PhysicsUtils = PhysicsUtils;
}

// Control handler for the racing game
const ControlHandler = {
  // Player input state
  input: {
    forward: 0,
    backward: 0,
    steering: 0,
    boost: false,
    drift: 0
  },

  // Keyboard mapping
  keyMap: {
    'KeyW': 'forward',
    'ArrowUp': 'forward',
    'KeyS': 'backward',
    'ArrowDown': 'backward',
    'KeyA': 'steeringLeft',
    'ArrowLeft': 'steeringLeft',
    'KeyD': 'steeringRight',
    'ArrowRight': 'steeringRight',
    'Space': 'boost'
  },

  // Initialize controls
  init(container = document) {
    this.container = container;
    this.setupKeyboardListeners();
  },

  // Set up keyboard event listeners
  setupKeyboardListeners() {
    this.container.addEventListener('keydown', (e) => this.handleKeyDown(e));
    this.container.addEventListener('keyup', (e) => this.handleKeyUp(e));
  },

  // Handle key down events
  handleKeyDown(e) {
    const action = this.keyMap[e.code];
    if (action) {
      e.preventDefault();

      switch (action) {
        case 'forward':
          this.input.forward = 1;
          break;
        case 'backward':
          this.input.backward = -0.5;
          break;
        case 'steeringLeft':
          this.input.steering = Math.max(-1, this.input.steering - 0.2);
          break;
        case 'steeringRight':
          this.input.steering = Math.min(1, this.input.steering + 0.2);
          break;
        case 'boost':
          this.input.boost = true;
          break;
      }
    }
  },

  // Handle key up events
  handleKeyUp(e) {
    const action = this.keyMap[e.code];
    if (action) {
      e.preventDefault();

      switch (action) {
        case 'forward':
          if (this.input.backward === 1) this.input.backward = 0;
          break;
        case 'backward':
          if (this.input.backward === -0.5) this.input.backward = 0;
          break;
        case 'steeringLeft':
          if (this.input.steering < 0) this.input.steering = Math.min(0, this.input.steering + 0.2);
          break;
        case 'steeringRight':
          if (this.input.steering > 0) this.input.steering = Math.max(0, this.input.steering - 0.2);
          break;
        case 'boost':
          this.input.boost = false;
          break;
      }
    }
  },

  // Get input for physics simulation
  getPhysicsInput(dt) {
    // Calculate drift based on steering and speed
    const speed = Math.sqrt(this.input.forward ** 2 + this.input.backward ** 2);
    const steeringForce = Math.abs(this.input.steering);

    // Drift only when moving and steering
    if (speed > 0.1 && steeringForce > 0.1) {
      this.input.drift = Math.min(100, this.input.drift + (steeringForce * 20 * dt));
    } else {
      // Decay drift when not steering
      this.input.drift = Math.max(0, this.input.drift - (10 * dt));
    }

    return {
      forward: this.input.forward,
      backward: this.input.backward,
      steering: this.input.steering,
      boost: this.input.boost,
      drift: this.input.drift
    };
  },

  // Reset input
  reset() {
    this.input = {
      forward: 0,
      backward: 0,
      steering: 0,
      boost: false,
      drift: 0
    };
  },

  // Get current input state
  getInput() {
    return { ...this.input };
  },

  // Check if any input is active
  isAnyInputActive() {
    return this.input.forward !== 0 || 
           this.input.backward !== 0 || 
           this.input.steering !== 0 || 
           this.input.boost || 
           this.input.drift > 0;
  }
};

// Export for use in other modules
if (typeof module !== 'undefined' && module.exports) {
  module.exports = ControlHandler;
}
if (typeof window !== 'undefined') {
  window.ControlHandler = ControlHandler;
}

