// Audio system for the racing game
const AudioSystem = {
  audioContext: null,
  masterVolume: 0.7,
  sounds: {},
  backgroundMusic: null,

  // Initialize audio system
  init() {
    try {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      this.audioContext.resume();
    } catch (error) {
      console.log('Audio not supported:', error);
    }
  },

  // Load and play sound effect
  playSound(soundName, options = {}) {
    if (!this.audioContext) return;

    const sound = this.sounds[soundName];
    if (!sound) {
      console.warn(`Sound ${soundName} not found`);
      return;
    }

    const source = this.audioContext.createBufferSource();
    source.buffer = sound;

    const gainNode = this.audioContext.createGain();
    gainNode.gain.value = options.volume || 1;

    source.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    source.start(0);

    if (options.loop) {
      source.loop = true;
      this.backgroundMusic = source;
    }
  },

  // Create a simple engine sound
  createEngineSound() {
    if (!this.audioContext) return;

    const createOscillator = (frequency, type = 'sine') => {
      const oscillator = this.audioContext.createOscillator();
      oscillator.type = type;
      oscillator.frequency.setValueAtTime(frequency, this.audioContext.currentTime);
      return oscillator;
    };

    // Create engine sound with multiple oscillators
    const osc1 = createOscillator(80, 'sawtooth');
    const osc2 = createOscillator(120, 'sawtooth');
    const osc3 = createOscillator(200, 'triangle');

    const gainNode = this.audioContext.createGain();
    gainNode.gain.setValueAtTime(0, this.audioContext.currentTime);
    gainNode.gain.linearRampToValueAtTime(0.1, this.audioContext.currentTime + 0.5);

    osc1.connect(gainNode);
    osc2.connect(gainNode);
    osc3.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    osc1.start();
    osc2.start();
    osc3.start();

    // Create engine animation
    let speed = 80;
    const engineAnimation = () => {
      osc1.frequency.setValueAtTime(speed, this.audioContext.currentTime);
      osc2.frequency.setValueAtTime(speed * 1.5, this.audioContext.currentTime);
      osc3.frequency.setValueAtTime(speed * 2.5, this.audioContext.currentTime);

      speed += (Math.random() - 0.5) * 10;
      speed = Math.max(60, Math.min(150, speed));

      requestAnimationFrame(engineAnimation);
    };

    engineAnimation();

    return { osc1, osc2, osc3, gainNode };
  },

  // Play drift sound
  playDriftSound() {
    if (!this.audioContext) return;

    const oscillator = this.audioContext.createOscillator();
    oscillator.type = 'sawtooth';
    oscillator.frequency.setValueAtTime(200, this.audioContext.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(400, this.audioContext.currentTime + 0.2);

    const gainNode = this.audioContext.createGain();
    gainNode.gain.setValueAtTime(0, this.audioContext.currentTime);
    gainNode.gain.linearRampToValueAtTime(0.1, this.audioContext.currentTime + 0.1);
    gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.5);

    oscillator.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    oscillator.start();
    oscillator.stop(this.audioContext.currentTime + 0.5);
  },

  // Play boost sound
  playBoostSound() {
    if (!this.audioContext) return;

    const oscillator = this.audioContext.createOscillator();
    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(400, this.audioContext.currentTime);
    oscillator.frequency.linearRampToValueAtTime(800, this.audioContext.currentTime + 0.1);

    const gainNode = this.audioContext.createGain();
    gainNode.gain.setValueAtTime(0, this.audioContext.currentTime);
    gainNode.gain.linearRampToValueAtTime(0.2, this.audioContext.currentTime + 0.1);
    gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.3);

    oscillator.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    oscillator.start();
    oscillator.stop(this.audioContext.currentTime + 0.3);
  },

  // Play collision sound
  playCollisionSound() {
    if (!this.audioContext) return;

    const oscillator = this.audioContext.createOscillator();
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(150, this.audioContext.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(50, this.audioContext.currentTime + 0.3);

    const gainNode = this.audioContext.createGain();
    gainNode.gain.setValueAtTime(0, this.audioContext.currentTime);
    gainNode.gain.linearRampToValueAtTime(0.15, this.audioContext.currentTime + 0.1);
    gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.5);

    oscillator.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    oscillator.start();
    oscillator.stop(this.audioContext.currentTime + 0.5);
  },

  // Play background music
  playBackgroundMusic() {
    if (!this.audioContext) return;

    this.playSound('background', { loop: true });
  },

  // Set master volume
  setVolume(volume) {
    this.masterVolume = Math.max(0, Math.min(1, volume));
  }
};

// Export for use in other modules
if (typeof module !== 'undefined' && module.exports) {
  module.exports = AudioSystem;
}
if (typeof window !== 'undefined') {
  window.AudioSystem = AudioSystem;
}

// Test script for the Mario Kart 3D Racer game
const TestRunner = {
  tests: [],
  results: { passed: 0, failed: 0 },

  // Add a test
  addTest(name, testFn) {
    this.tests.push({ name, testFn });
  },

  // Run all tests
  async runAll() {
    console.log('Running tests for Mario Kart 3D Racer...');
    console.log('=' .repeat(50));

    for (const test of this.tests) {
      try {
        await test.testFn();
        console.log(`✓ ${test.name} - PASSED`);
        this.results.passed++;
      } catch (error) {
        console.log(`✗ ${test.name} - FAILED`);
        console.log(`  Error: ${error.message}`);
        this.results.failed++;
      }
    }

    console.log('=' .repeat(50));
    console.log(`Tests completed: ${this.results.passed + this.results.failed}`);
    console.log(`Passed: ${this.results.passed}`);
    console.log(`Failed: ${this.results.failed}`);

    if (this.results.failed === 0) {
      console.log('\n🎉 All tests passed!');
    } else {
      console.log('\n❌ Some tests failed');
    }

    return this.results;
  }
};

// Test functions
function testThreeJS() {
  return new Promise((resolve, reject) => {
    if (typeof THREE === 'undefined') {
      reject(new Error('Three.js not loaded'));
      return;
    }

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();

    // Test basic Three.js functionality
    const geometry = new THREE.BoxGeometry(1, 1, 1);
    const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
    const cube = new THREE.Mesh(geometry, material);
    scene.add(cube);

    if (scene.children.length !== 1) {
      throw new Error('Scene does not contain the cube');
    }

    if (!(cube.geometry instanceof THREE.BoxGeometry)) {
      throw new Error('Cube is not a BoxGeometry');
    }

    if (!(cube.material instanceof THREE.MeshBasicMaterial)) {
      throw new Error('Cube material is not MeshBasicMaterial');
    }

    resolve();
  });
}

function testCannonJS() {
  return new Promise((resolve, reject) => {
    if (typeof CANNON === 'undefined') {
      reject(new Error('Cannon.js not loaded'));
      return;
    }

    const world = new CANNON.World();
    world.gravity.set(0, -9.82, 0);

    const shape = new CANNON.Box(new CANNON.Vec3(1, 1, 1));
    const body = new CANNON.Body({ mass: 1, shape: shape });
    body.position.set(0, 5, 0);
    world.add(body);

    if (body.mass !== 1) {
      throw new Error('Body mass is not 1');
    }

    if (body.position.x !== 0 || body.position.y !== 5 || body.position.z !== 0) {
      throw new Error('Body position is incorrect');
    }

    if (world.bodies.length !== 1) {
      throw new Error('World does not contain the body');
    }

    resolve();
  });
}

function testGameFiles() {
  return new Promise((resolve, reject) => {
    const fs = require('fs');
    const path = require('path');

    const requiredFiles = [
      'src/Game.js',
      'src/scene.js',
      'src/ThreeUtils.js',
      'src/PhysicsUtils.js',
      'src/ControlHandler.js',
      'src/AudioSystem.js',
      'index.html',
      'README.md'
    ];

    const missingFiles = [];
    requiredFiles.forEach(file => {
      const filePath = path.join(__dirname, '..', file);
      if (!fs.existsSync(filePath)) {
        missingFiles.push(file);
      }
    });

    if (missingFiles.length > 0) {
      throw new Error(`Missing files: ${missingFiles.join(', ')}`);
    }

    resolve();
  });
}

function testHTMLStructure() {
  return new Promise((resolve, reject) => {
    const fs = require('fs');
    const path = require('path');

    const htmlPath = path.join(__dirname, '..', 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    // Check for required HTML elements
    const requiredElements = [
      '<canvas',
      'id="game-container"',
      'id="start-screen"',
      'id="game-over"',
      'Three.js',
      'Cannon.js'
    ];

    for (const element of requiredElements) {
      if (!html.includes(element)) {
        throw new Error(`HTML does not contain required element: ${element}`);
      }
    }

    resolve();
  });
}

function testPackageJSON() {
  return new Promise((resolve, reject) => {
    const fs = require('fs');
    const path = require('path');

    const packagePath = path.join(__dirname, '..', 'package.json');
    const packageJson = JSON.parse(fs.readFileSync(packagePath, 'utf8'));

    const requiredFields = ['name', 'version', 'main', 'scripts'];

    for (const field of requiredFields) {
      if (!packageJson[field]) {
        throw new Error(`package.json missing field: ${field}`);
      }
    }

    if (!packageJson.scripts.start) {
      throw new Error('package.json missing start script');
    }

    resolve();
  });
}

// Add tests to the test runner
TestRunner.addTest('Three.js Library', testThreeJS);
TestRunner.addTest('Cannon.js Library', testCannonJS);
TestRunner.addTest('Required Game Files', testGameFiles);
TestRunner.addTest('HTML Structure', testHTMLStructure);
TestRunner.addTest('Package.json Configuration', testPackageJSON);

// Run tests if this is the main module
if (require.main === module) {
  TestRunner.runAll().then(results => {
    process.exit(results.failed > 0 ? 1 : 0);
  });
}

module.exports = TestRunner;

// Development script for the Mario Kart 3D Racer game
const DevTools = {
  // Watch for file changes and reload browser
  watchFiles() {
    const fs = require('fs');
    const path = require('path');
    const chokidar = require('chokidar');

    const srcDir = path.join(__dirname, '../src');
    const distDir = path.join(__dirname, '../dist');

    // Watch source files
    const watcher = chokidar.watch([
      `${srcDir}/**/*.js`,
      `${srcDir}/**/*.css`,
      `${srcDir}/**/*.html`
    ], {
      ignored: /node_modules/,
      persistent: true
    });

    let rebuildTimer = null;

    watcher.on('change', (filePath) => {
      console.log(`File changed: ${path.relative(srcDir, filePath)}`);

      if (rebuildTimer) {
        clearTimeout(rebuildTimer);
      }

      rebuildTimer = setTimeout(() => {
        console.log('Rebuilding due to file changes...');
        this.rebuild();
      }, 500);
    });

    watcher.on('add', (filePath) => {
      console.log(`File added: ${path.relative(srcDir, filePath)}`);
    });

    watcher.on('unlink', (filePath) => {
      console.log(`File removed: ${path.relative(srcDir, filePath)}`);
      this.rebuild();
    });

    console.log('Watching for file changes...');
    return watcher;
  },

  // Build the project
  async rebuild() {
    const fs = require('fs');
    const path = require('path');

    try {
      // Build JavaScript files
      await this.buildJS();

      // Copy other files
      this.copyStaticFiles();

      console.log('✓ Rebuild complete');
    } catch (error) {
      console.error('✗ Rebuild failed:', error.message);
    }
  },

  // Build JavaScript files
  async buildJS() {
    const fs = require('fs').promises;
    const path = require('path');
    const Terser = require('terser');

    const srcDir = path.join(__dirname, '../src');
    const distDir = path.join(__dirname, '../dist');

    // Ensure dist directory exists
    await fs.mkdir(distDir, { recursive: true });

    // Process each JavaScript file
    const files = [
      'Game.js',
      'scene.js',
      'ThreeUtils.js',
      'PhysicsUtils.js',
      'ControlHandler.js',
      'AudioSystem.js'
    ];

    for (const file of files) {
      const srcPath = path.join(srcDir, file);
      const distPath = path.join(distDir, file);

      try {
        const content = await fs.readFile(srcPath, 'utf8');
        const minified = await Terser.minify(content, {
          mangle: true,
          compress: true,
          format: {
            comments: false
          }
        });

        await fs.writeFile(distPath, minified.code);
        console.log(`✓ Built ${file}`);
      } catch (error) {
        console.warn(`⚠ Failed to build ${file}: ${error.message}`);
      }
    }
  },

  // Copy static files
  copyStaticFiles() {
    const fs = require('fs');
    const path = require('path');

    const srcDir = path.join(__dirname, '..');
    const distDir = path.join(__dirname, '../dist');

    // Copy index.html
    const htmlSrc = path.join(srcDir, 'index.html');
    const htmlDest = path.join(distDir, 'index.html');

    if (fs.existsSync(htmlSrc)) {
      fs.copyFileSync(htmlSrc, htmlDest);
      console.log('✓ Copied index.html');
    }

    // Copy README.md
    const readmeSrc = path.join(srcDir, 'README.md');
    const readmeDest = path.join(distDir, 'README.md');

    if (fs.existsSync(readmeSrc)) {
      fs.copyFileSync(readmeSrc, readmeDest);
      console.log('✓ Copied README.md');
    }
  },

  // Start development server
  startDevServer() {
    const http = require('http');
    const fs = require('fs');
    const path = require('path');
    const url = require('url');

    const distDir = path.join(__dirname, '../dist');
    const server = http.createServer((req, res) => {
      const parsedUrl = url.parse(req.url);
      let filePath = path.join(distDir, parsedUrl.pathname);

      if (parsedUrl.pathname === '/') {
        filePath = path.join(distDir, 'index.html');
      }

      fs.readFile(filePath, (err, data) => {
        if (err) {
          res.writeHead(404);
          res.end('File not found');
          return;
        }

        const ext = path.extname(filePath);
        const contentType = this.getContentType(ext);

        res.writeHead(200, { 'Content-Type': contentType });
        res.end(data);
      });
    });

    const port = 3000;
    server.listen(port, () => {
      console.log(`Development server running at http://localhost:${port}`);
      console.log('Press Ctrl+C to stop the server');
    });

    return server;
  },

  // Get content type based on file extension
  getContentType(ext) {
    const contentTypes = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.jpeg': 'image/jpeg',
      '.gif': 'image/gif',
      '.svg': 'image/svg+xml',
      '.woff': 'font/woff',
      '.woff2': 'font/woff2',
      '.ttf': 'font/ttf',
      '.eot': 'application/vnd.ms-fontobject'
    };

    return contentTypes[ext] || 'text/plain';
  }
};

// Run development mode
async function runDevMode() {
  console.log('Starting Mario Kart 3D Racer development mode...');

  // Check if required modules are installed
  try {
    require('chokidar');
  } catch (error) {
    console.log('Installing chokidar...');
    require('child_process').execSync('npm install chokidar', { stdio: 'inherit' });
  }

  try {
    require('terser');
  } catch (error) {
    console.log('Installing terser...');
    require('child_process').execSync('npm install terser', { stdio: 'inherit' });
  }

  // Build initially
  await DevTools.rebuild();

  // Start watching for changes
  const watcher = DevTools.watchFiles();

  // Start development server
  const server = DevTools.startDevServer();

  // Handle graceful shutdown
  process.on('SIGINT', () => {
    console.log('\nShutting down...');
    watcher.close();
    server.close();
    process.exit(0);
  });
}

// Run if this is the main module
if (require.main === module) {
  runDevMode().catch(console.error);
}

module.exports = DevTools;

