input.content:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    margin: 0;
    padding: 0;
    overflow: hidden;
    background: #000;
    font-family: 'Orbitron', sans-serif;
    user-select: none;
}

#game-container {
    width: 100vw;
    height: 100vh;
}

#controls {
    position: absolute;
    top: 10px;
    left: 10px;
    color: white;
    background: rgba(0, 0, 0, 0.7);
    padding: 15px;
    border-radius: 8px;
    font-size: 14px;
    border: 2px solid #ff6600;
}

#controls h3 {
    margin: 0 0 10px 0;
    color: #ff6600;
    text-shadow: 0 0 10px rgba(255, 102, 0, 0.5);
}

#controls ul {
    margin: 0;
    padding-left: 20px;
}

#controls li {
    margin: 5px 0;
    position: relative;
    padding-left: 20px;
}

#controls li:before {
    content: '▶';
    position: absolute;
    left: 0;
    color: #ff6600;
}

#info {
    position: absolute;
    top: 10px;
    right: 10px;
    color: white;
    background: rgba(0, 0, 0, 0.7);
    padding: 15px;
    border-radius: 8px;
    font-size: 14px;
    border: 2px solid #00ff00;
}

#info h3 {
    margin: 0 0 10px 0;
    color: #00ff00;
    text-shadow: 0 0 10px rgba(0, 255, 0, 0.5);
}

#start-screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    transition: opacity 1s ease;
}

#start-screen.hidden {
    opacity: 0;
    pointer-events: none;
}

#start-button {
    padding: 20px 40px;
    font-size: 24px;
    background: linear-gradient(135deg, #ff6600, #ffaa00);
    color: white;
    border: none;
    border-radius: 12px;
    cursor: pointer;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    transition: all 0.3s ease;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 2px;
}

#start-button:hover {
    background: linear-gradient(135deg, #ff7700, #ffbb00);
    transform: translateY(-2px);
    box-shadow: 0 12px 40px rgba(255, 102, 0, 0.4);
}

#game-over {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.8);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 1001;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
}

#game-over.visible {
    opacity: 1;
    pointer-events: all;
}

#game-over h2 {
    color: #ff6600;
    font-size: 48px;
    margin-bottom: 20px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
    animation: pulse 2s infinite;
}

#game-over p {
    color: #ccc;
    font-size: 20px;
    margin-bottom: 30px;
}

#restart-button {
    padding: 15px 30px;
    font-size: 18px;
    background: linear-gradient(135deg, #00ff00, #00cc00);
    color: black;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    font-weight: 600;
    text-transform: uppercase;
}

#restart-button:hover {
    background: linear-gradient(135deg, #00ff00, #00ee00);
    opacity: 0.8;
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0, 255, 0, 0.3);
}

#score {
    position: absolute;
    top: 60px;
    left: 10px;
    color: #ff6600;
    font-size: 24px;
    font-weight: bold;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
    animation: glow 1.5s infinite alternate;
}

@keyframes pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
}

@keyframes glow {
    from { text-shadow: 0 0 10px rgba(255, 102, 0, 0.5); }
    to { text-shadow: 0 0 20px rgba(255, 102, 0, 0.8), 0 0 30px rgba(255, 102, 0, 0.6); }
}

@media (max-width: 768px) {
    #controls {
        display: none;
    }

    #start-button {
        padding: 15px 30px;
        font-size: 20px;
    }

    #game-over h2 {
        font-size: 36px;
    }
}

